CREATE TABLE livestock_species(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,category ENUM('livestock','poultry','fish') NOT NULL,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE livestock_facilities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,code VARCHAR(60) NOT NULL,name VARCHAR(150) NOT NULL,facility_type ENUM('housing','poultry_house','pond') NOT NULL,area_m2 DECIMAL(12,3) NULL,capacity_heads INT UNSIGNED NULL,status ENUM('active','inactive','maintenance') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uq_lf_site_code(site_id,code),CONSTRAINT fk_lf_site FOREIGN KEY(site_id) REFERENCES sites(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE livestock_batches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,species_id INT UNSIGNED NOT NULL,facility_id BIGINT UNSIGNED NOT NULL,batch_number VARCHAR(100) NOT NULL UNIQUE,purpose ENUM('breeding','meat','laying','fattening') NOT NULL,started_at DATE NOT NULL,initial_heads INT UNSIGNED NOT NULL,current_heads INT UNSIGNED NOT NULL,initial_average_weight_kg DECIMAL(10,3) NULL,current_average_weight_kg DECIMAL(10,3) NULL,status ENUM('active','completed','cancelled') DEFAULT 'active',created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,KEY idx_lb_site_status(site_id,status),CONSTRAINT fk_lb_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_lb_species FOREIGN KEY(species_id) REFERENCES livestock_species(id),CONSTRAINT fk_lb_facility FOREIGN KEY(facility_id) REFERENCES livestock_facilities(id),CONSTRAINT fk_lb_creator FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE livestock_head_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,movement_type ENUM('stocking','birth','mortality','sale','slaughter','transfer_out','correction','reversal') NOT NULL,quantity_heads INT UNSIGNED NOT NULL,heads_before INT UNSIGNED NOT NULL,heads_after INT UNSIGNED NOT NULL,reference_type VARCHAR(80) NOT NULL,reference_id BIGINT UNSIGNED NOT NULL,movement_at DATETIME NOT NULL,reason VARCHAR(255) NULL,created_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_lhm_effect(batch_id,movement_type,reference_type,reference_id),CONSTRAINT fk_lhm_batch FOREIGN KEY(batch_id) REFERENCES livestock_batches(id),CONSTRAINT fk_lhm_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE livestock_feedings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,feed_product_id INT UNSIGNED NULL,quantity_kg DECIMAL(12,3) NOT NULL,fed_at DATETIME NOT NULL,unit_cost DECIMAL(14,4) NOT NULL DEFAULT 0,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,CONSTRAINT fk_lfeed_batch FOREIGN KEY(batch_id) REFERENCES livestock_batches(id),CONSTRAINT fk_lfeed_product FOREIGN KEY(feed_product_id) REFERENCES products(id),CONSTRAINT fk_lfeed_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE livestock_weighings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,sample_heads INT UNSIGNED NOT NULL,total_weight_kg DECIMAL(12,3) NOT NULL,average_weight_kg DECIMAL(10,3) NOT NULL,weighed_at DATETIME NOT NULL,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_lw_batch FOREIGN KEY(batch_id) REFERENCES livestock_batches(id),CONSTRAINT fk_lw_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE poultry_productions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,production_date DATE NOT NULL,eggs_count INT UNSIGNED NOT NULL DEFAULT 0,mortality_heads INT UNSIGNED NOT NULL DEFAULT 0,sold_heads INT UNSIGNED NOT NULL DEFAULT 0,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_pp_batch_date(batch_id,production_date),CONSTRAINT fk_pp_batch FOREIGN KEY(batch_id) REFERENCES livestock_batches(id),CONSTRAINT fk_pp_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fish_stockings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,stocked_heads INT UNSIGNED NOT NULL,total_weight_kg DECIMAL(12,3) NULL,stocked_at DATETIME NOT NULL,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_fstock_batch FOREIGN KEY(batch_id) REFERENCES livestock_batches(id),CONSTRAINT fk_fstock_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fish_catches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,catch_number VARCHAR(100) NOT NULL UNIQUE,heads_caught INT UNSIGNED NOT NULL,gross_weight_kg DECIMAL(12,3) NOT NULL,tare_weight_kg DECIMAL(12,3) NOT NULL DEFAULT 0,net_weight_kg DECIMAL(12,3) NOT NULL,yield_kg_m2 DECIMAL(12,4) NOT NULL,status ENUM('submitted','validated','cancelled') DEFAULT 'submitted',caught_at DATETIME NOT NULL,created_by INT UNSIGNED NOT NULL,validated_by INT UNSIGNED NULL,validated_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_fc_batch FOREIGN KEY(batch_id) REFERENCES livestock_batches(id),CONSTRAINT fk_fc_creator FOREIGN KEY(created_by) REFERENCES users(id),CONSTRAINT fk_fc_validator FOREIGN KEY(validated_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE livestock_conversions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,conversion_number VARCHAR(100) NOT NULL UNIQUE,conversion_type ENUM('slaughter','fish_catch','formal_weighing') NOT NULL,input_heads INT UNSIGNED NOT NULL,gross_weight_kg DECIMAL(12,3) NOT NULL,tare_weight_kg DECIMAL(12,3) NOT NULL DEFAULT 0,net_weight_kg DECIMAL(12,3) NOT NULL,converted_at DATETIME NOT NULL,status ENUM('submitted','validated','cancelled') DEFAULT 'submitted',created_by INT UNSIGNED NOT NULL,validated_by INT UNSIGNED NULL,validated_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_lc_batch FOREIGN KEY(batch_id) REFERENCES livestock_batches(id),CONSTRAINT fk_lc_creator FOREIGN KEY(created_by) REFERENCES users(id),CONSTRAINT fk_lc_validator FOREIGN KEY(validated_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE livestock_weight_stocks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,batch_id BIGINT UNSIGNED NOT NULL,conversion_id BIGINT UNSIGNED NOT NULL,quantity_kg DECIMAL(12,3) NOT NULL,reserved_kg DECIMAL(12,3) NOT NULL DEFAULT 0,status ENUM('available','reserved','in_transit','depleted','cancelled') DEFAULT 'available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_lws_conversion(conversion_id),CONSTRAINT fk_lws_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_lws_batch FOREIGN KEY(batch_id) REFERENCES livestock_batches(id),CONSTRAINT fk_lws_conversion FOREIGN KEY(conversion_id) REFERENCES livestock_conversions(id),CONSTRAINT chk_lws_nonnegative CHECK(quantity_kg>=0 AND reserved_kg>=0 AND reserved_kg<=quantity_kg)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE livestock_weight_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,stock_id BIGINT UNSIGNED NOT NULL,movement_type ENUM('conversion_in','reserve','transfer_out','release','reversal') NOT NULL,quantity_kg DECIMAL(12,3) NOT NULL,stock_before_kg DECIMAL(12,3) NOT NULL,stock_after_kg DECIMAL(12,3) NOT NULL,reserved_before_kg DECIMAL(12,3) NOT NULL,reserved_after_kg DECIMAL(12,3) NOT NULL,reference_type VARCHAR(80) NOT NULL,reference_id BIGINT UNSIGNED NOT NULL,created_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_lwm_effect(stock_id,movement_type,reference_type,reference_id),CONSTRAINT fk_lwm_stock FOREIGN KEY(stock_id) REFERENCES livestock_weight_stocks(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE livestock_transfers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,weight_stock_id BIGINT UNSIGNED NULL,source_site_id INT UNSIGNED NOT NULL,destination_site_id INT UNSIGNED NOT NULL,transfer_number VARCHAR(100) NOT NULL UNIQUE,source_unit ENUM('head','kg') NOT NULL,quantity_heads INT UNSIGNED NULL,quantity_kg DECIMAL(12,3) NULL,status ENUM('draft','approved','in_transit','received','cancelled') DEFAULT 'draft',truck_plate VARCHAR(40) NULL,driver_name VARCHAR(150) NULL,created_by INT UNSIGNED NOT NULL,approved_by INT UNSIGNED NULL,dispatched_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,dispatched_at DATETIME NULL,received_at DATETIME NULL,deleted_at TIMESTAMP NULL,UNIQUE KEY uq_lt_batch_active(batch_id),CONSTRAINT fk_lt_batch FOREIGN KEY(batch_id) REFERENCES livestock_batches(id),CONSTRAINT fk_lt_weight FOREIGN KEY(weight_stock_id) REFERENCES livestock_weight_stocks(id),CONSTRAINT fk_lt_source FOREIGN KEY(source_site_id) REFERENCES sites(id),CONSTRAINT fk_lt_destination FOREIGN KEY(destination_site_id) REFERENCES sites(id),CONSTRAINT fk_lt_creator FOREIGN KEY(created_by) REFERENCES users(id),CONSTRAINT fk_lt_approver FOREIGN KEY(approved_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT IGNORE INTO livestock_species(code,name,category) VALUES('BOVIN','Bovin','livestock'),('PORC','Porc','livestock'),('POULET','Poulet','poultry'),('TILAPIA','Tilapia','fish');
INSERT IGNORE INTO permissions(component,action,description) VALUES('livestock','read','Consulter élevages'),('livestock','create','Créer élevages'),('livestock','validate','Valider conversions et BTR'),('livestock','update','Saisir événements élevage'),('livestock','delete','Annuler opérations élevage'),('livestock','administer','Administrer élevages');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='livestock' WHERE r.slug IN('administrateur','administrateur-systeme');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='livestock' AND p.action IN('read','create','update') WHERE r.slug IN('responsable-site','directeur-site','operateur-saisie');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='livestock' AND p.action IN('read','validate') WHERE r.slug IN('direction','directeur-general','directeur-site');
